 bool routeServices(ControllerDeviceState&d,Services s){if(bound_!=&d||!active_||!boundServices(d,s))return false;if(child_!=Child::None)return true;auto r=request();if(r.service==Service::None)return true;switch(r.service){case Service::Dsp:if(s.dsp.active()||!s.dsp.startWrite(r.address,r.word))return false;child_=Child::Dsp;break;case Service::Panel:if(s.refresh.active()||s.panel.active()||s.dsp.active()||!s.refresh.start())return false;child_=Child::Panel;break;case Service::Init:if(s.init.active()||!s.init.start(r.part))return false;child_=Child::Init;break;case Service::Release:if(s.voices.active()||s.dsp.active()||!s.voices.start(r.part,true))return false;child_=Child::Release;break;default:break;}return true;}
 unsigned nextClocks(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq,Services s)const{if(bound_!=&d||!active_||!irq.boundTo(d)||!boundServices(d,s)||d.interruptMode2||d.pendingIrqsHigh||irq.active()||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return 0;if(child_==Child::Dsp)return s.dsp.nextClocks(d,irq);if(child_==Child::Panel)return s.refresh.nextClocks(d,irq,s.panel,s.dsp);if(child_==Child::Init)return s.init.nextClocks(d,irq);if(child_==Child::Release)return s.voices.nextClocks(d,irq,s.dsp);if(request().service!=Service::None)return 0;auto cr=credits(d);auto n=index_?index_->nextClocks(cr):std::visit([&](const auto&t){using X=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<X,L>||std::is_same_v<X,C>)return t.nextClocks(d.lastWrite);else return t.nextClocks(cr);},task_);return n?n+(d.pendingIrqs?1u:0u):0;}
