private:static bool aliasesContextByte(uint32_t a){a&=0xffffff;return a>=0xfffea0&&a<0xffff10;}template<class V>static bool boundServices(const ControllerDeviceState&d,V s){return s.dsp.boundTo(d)&&s.panel.boundTo(d)&&s.refresh.boundTo(d)&&s.init.boundTo(d)&&s.voices.boundTo(d);}static bool aliasesContext(uint32_t source){for(unsigned i=0;i<128;++i){auto a=(source+i)&0xffffff;if(a>=0xfffea0&&a<0xffff10)return true;}return false;}static void check(bool p){if(!p)throw std::logic_error("K domain program state phase");}static uint32_t readTimed(ControllerDeviceState&d,unsigned a,unsigned n){uint32_t value=0;for(unsigned i=0;i<n;++i)value=(value<<8)|d.read8(a+i);return value;}
 Request request()const{return std::visit([](const auto&t)->Request{using X=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<X,L>){auto r=t.request();using S=L::Service;return {r.service==S::DspWrite?Service::Dsp:r.service==S::RefreshPanel?Service::Panel:r.service==S::InitializeVoice?Service::Init:r.service==S::ReleaseVoices?Service::Release:Service::None,r.address,r.word,r.part};}else if constexpr(std::is_same_v<X,C>){auto r=t.request();using S=C::Service;return {r.service==S::DspWrite?Service::Dsp:r.service==S::RefreshPanel?Service::Panel:r.service==S::InitializeVoice?Service::Init:Service::None,r.address,r.word,r.part};}else if constexpr(std::is_same_v<X,D>)return t.awaiting()?Request{Service::Dsp,0x802b,1,0}:Request{};else return {};},task_);}
